    and (
        s.submit_user_id = #{userId}
        or exists (
            select 1 from biz_research_group_member leader
            where leader.group_id = s.group_id and leader.user_id = #{userId}
              and leader.member_role = 'LEADER' and leader.status = '0'
        )
        or (s.status = '3' and exists (
            select 1 from biz_research_group_member member
            where member.group_id = s.group_id and member.user_id = #{userId}
              and member.status = '0'
        ))
    )

and s.group_id = #{query.groupId}
and s.framework_id = #{query.frameworkId}
and s.task_id = #{query.taskId}
and s.deliverable_id = #{query.deliverableId}
and s.submit_user_id = #{query.submitUserId}
and s.status = #{query.status}

    and s.submission_name like concat('%', #{query.submissionName}, '%')

order by s.create_time desc, s.submission_id desc


and s.deliverable_id = #{deliverableId}
and s.submit_user_id = #{userId}
order by coalesce(s.update_time, s.create_time) desc, s.submission_id desc

