update task_submission
set submission_name = #{submissionName}, submission_desc = #{submissionDesc},
    update_by = #{updateBy}, update_time = sysdate(), version = version + 1
where submission_id = #{submissionId} and deliverable_id = #{deliverableId}
  and status in ('0', '2') and del_flag = '0' and version = #{version}
